// Helper function to count opening brackets
function countOpening(s: string, upTo: int): int
    requires 0 <= upTo <= |s|
{
    var count := 0;
    var i := 0;
    while i < upTo
        invariant 0 <= count <= i
        invariant i <= |s|
    {
        if s[i] == '<' {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

// Helper function to count closing brackets
function countClosing(s: string, upTo: int): int
    requires 0 <= upTo <= |s|
{
    var count := 0;
    var i := 0;
    while i < upTo
        invariant 0 <= count <= i
        invariant i <= |s|
    {
        if s[i] == '>' {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

